"""Versioned, manually specified command targets; never generated by a tested model."""
from copy import deepcopy

SUITE_VERSION = "control-150-v3"


def main_cases():
    rows = []
    def pair(category, texts, steps, skill, **context):
        group = f"{category}-{len(rows)}"
        for wording, text in zip(("direct", "paraphrase"), texts):
            index = sum(r["category"] == category for r in rows) + 1
            rows.append({"id": f"{category[0].upper()}{index:02}", "category": category,
                         "command": text, "expected": {"steps": deepcopy(steps)},
                         "suite_version": SUITE_VERSION, "pair_id": group,
                         "wording": wording, "skill": skill, **deepcopy(context)})
    for action, texts in [
        ("open", ("open the hand", "Extend all fingers into the open-hand gesture")),
        ("close", ("make a fist", "Form a closed fist")),
        ("point", ("point", "Make the pointing gesture")),
        ("peace", ("show peace", "Give me the V sign")),
        ("yes", ("show yes", "Give me a thumbs-up gesture")),
        ("no", ("show no", "Wag the index finger to indicate no")),
        ("ok", ("show ok", "Make the OK gesture")),
        ("wave", ("wave hello", "Greet me with a wave of the hand"))]:
        pair("pose", texts, [{"action": action}], "named_gesture")
    pair("pose", ("open hand at speed 2", "Use the open-hand gesture with motor speed set to two"),
         [{"action": "open", "speed": 2}], "speed")
    pair("pose", ("close hand for 2 seconds", "Hold the closed-fist gesture for two seconds"),
         [{"action": "close", "hold_seconds": 2}], "duration")
    # Non-target fingers start at known, asymmetric openings: accidental whole-hand
    # commands cannot satisfy a single-finger reference by coincidence.
    initial = {"index": 20, "middle": 40, "ring": 60, "thumb": 80}
    for finger, value in [("index", 0), ("middle", 100), ("ring", 25), ("thumb", 75),
                          ("index", 60), ("middle", 35), ("ring", 85), ("thumb", 10)]:
        pair("finger", (f"set {finger} to {value}%", f"Change only the {finger} finger to {value} percent opening"),
             [{"action": "pose", "fingers": {finger: value}}], "absolute_target", targets=initial)
    for finger in initial:
        for verb,delta in (("open",10),("close",10)):
            target=initial[finger]+(delta if verb=="open" else -delta)
            index=sum(r["category"]=="finger" for r in rows)+1
            rows.append({"id":f"F{index:02}","category":"finger","command":f"{verb} {finger} by {delta}%",
                         "expected":{"steps":[{"action":"pose","fingers":{finger:target}}]},
                         "targets":deepcopy(initial),"suite_version":SUITE_VERSION,"skill":"relative_target"})
        pair("finger", ("open it by 20%", "Increase that finger's opening by twenty percentage points"),
             [{"action":"pose","fingers":{finger:initial[finger]+20}}], "context_reference",targets=initial,
             previous={"steps":[{"action":"pose","fingers":{finger:initial[finger]}}]})
    from itertools import combinations
    for first,second in combinations(initial,2):
        pair("finger", (f"set {first} to 25% and {second} to 75%",
                        f"Leave the {first} one-quarter open and the {second} three-quarters open; keep the other fingers unchanged"),
             [{"action":"pose","fingers":{first:25,second:75}}],"multi_finger",targets=initial)
    for actions in [("open", "close"), ("close", "open"), ("point", "open"), ("open", "point"),
                    ("yes", "no"), ("no", "yes"), ("peace", "close"), ("ok", "open"),
                    ("open", "close", "open"), ("close", "open", "close"),
                    ("point", "peace", "close"), ("yes", "open", "no")]:
        pair("sequence", (" then ".join("show " + a for a in actions),
                          "Perform these gestures in this exact order: " + ", followed by ".join(actions)),
             [{"action": a} for a in actions], "ordered_gestures")
    pair("sequence", ("set index to 25% then set index to 75% then set index to 25%",
                      "Move only the index to one-quarter, then three-quarters, then one-quarter opening"),
         [{"action": "pose", "fingers": {"index": v}} for v in (25, 75, 25)], "intermediate_targets", targets=initial)
    pair("sequence", ("open hand for 2 seconds then close hand for 1 second",
                      "Hold an open hand for two seconds, followed by a closed fist for one second"),
         [{"action": "open", "hold_seconds": 2}, {"action": "close", "hold_seconds": 1}], "timed_sequence")
    previous = {"steps": [{"action": "point"}, {"action": "open"}]}
    pair("sequence", ("repeat that", "Perform the previous two gestures again in the same order"),
         previous["steps"], "context_repeat", previous=previous)
    for actions in [("open","point","close","open"),("open","close","point","open"),("yes","no","yes","no")]:
        pair("sequence", (" then ".join("show "+a for a in actions),
                          "Perform these four gestures in order: "+", ".join(actions)),
             [{"action":a} for a in actions],"four_step_order")
    for texts, result, skill in [
        (("2 + 3", "Show the sum of two and three"), 5, "addition"),
        (("7 - 7", "Subtract seven from seven and show the result"), 0, "subtraction_zero"),
        (("4 * 5", "Show four multiplied by five"), 20, "multiplication_upper_bound"),
        (("12 / 3", "Divide twelve by three and display the answer"), 4, "division"),
        (("2 + 3 * 2", "Show two plus the product of three and two"), 8, "precedence"),
        (("6 + 7","Display the sum of six and seven"),13,"addition_groups"),
        (("14 - 5","Show fourteen minus five"),9,"subtraction_groups"),
        (("3 * 4","Display three times four"),12,"multiplication_groups"),
        (("18 / 3","Show eighteen divided by three"),6,"division_groups"),
        (("(2 + 3) * 2","Add two and three first, then multiply the result by two and display it"),10,"parentheses")]:
        pair("arithmetic", texts, [{"action": "number", "number": result}], skill)
    return rows


def robustness_cases():
    cases = [
        ("open it more", "missing_referent", {}),
        ("open index by 20%", "missing_initial_target", {}),
        ("repeat that", "missing_history", {}),
        ("set little finger to 50%", "unsupported_finger", {}),
        ("set index to -10%", "below_range", {}),
        ("open index by 30%", "relative_overflow", {"targets": {"index": 90}}),
        ("open hand at speed 99", "invalid_speed", {}),
        ("open hand for 99 seconds", "invalid_duration", {}),
        ("set index to 120%", "above_range", {}),
        ("8 / 0", "division_by_zero", {}),
        ("3 / 2", "fractional_result", {}),
        ("20 + 1", "unsupported_count", {}),
        ("set middle to 105%","above_range",{}),
        ("set ring to -5%","below_range",{}),
        ("set thumb to 101%","above_range",{}),
        ("close middle by 50%","relative_underflow",{"targets":{"middle":20}}),
        ("open ring by 50%","relative_overflow",{"targets":{"ring":70}}),
        ("close thumb by 30%","relative_underflow",{"targets":{"thumb":10}}),
        ("set index to 50% and middle to 120%","invalid_multi_finger",{}),
        ("open hand then set thumb to 150%","invalid_sequence",{}),
        ("close ring by 10%","missing_initial_target",{}),
        ("move that finger","missing_referent",{}),
        ("rotate the wrist by 30 degrees","unsupported_joint",{}),
        ("set pinky to 25%","unsupported_finger",{}),
        ("open hand at speed 0","invalid_speed",{}),
        ("close hand for 0 seconds","invalid_duration",{}),
        ("2 - 5","negative_count",{}),
        ("6 * 4","unsupported_count",{}),
        ("5 / 2","fractional_result",{}),
        ("0 / 0","division_by_zero",{})]
    return [{"id": f"R{i:02}", "category": "robustness", "command": text,
             "expected": {"steps": [{"action": "unknown"}]}, "expected_behavior": "no_motion",
             "suite_version": SUITE_VERSION, "skill": skill, **context}
            for i, (text, skill, context) in enumerate(cases, 1)]


def complete_cases(dataset):
    """Run exactly the selected command set; never append hidden extra trials."""
    return deepcopy(dataset)


def balanced_200():
    rows=main_cases()+robustness_cases()
    def pair(category,texts,steps,skill,**context):
        group=f"v4-{category}-{len(rows)}"
        for wording,text in zip(("direct","paraphrase"),texts):
            number=sum(r['category']==category for r in rows)+1
            rows.append({'id':f'{category[0].upper()}{number:02}','category':category,'command':text,
                         'expected':{'steps':deepcopy(steps)},'skill':skill,'pair_id':group,'wording':wording,**deepcopy(context)})
    for action,speed,hold in [('point',2,2),('peace',4,1),('yes',3,3),('ok',2,2.5),('open',1,4)]:
        pair('pose',(f'show {action} at speed {speed} for {hold} seconds',
                     f'Perform the {action} gesture using speed {speed} and hold it for {hold} seconds'),
             [{'action':action,'speed':speed,'hold_seconds':hold}],'gesture_parameters')
    initial={'index':20,'middle':40,'ring':60,'thumb':80}
    for finger in initial:
        pair('finger',(f'set {finger} to 50%',f'Leave only the {finger} halfway open'),
             [{'action':'pose','fingers':{finger:50}}],'absolute_target',targets=initial)
        pair('finger',(f'close {finger} by {initial[finger]}%',
                       f'Decrease only the {finger} opening by {initial[finger]} percentage points'),
             [{'action':'pose','fingers':{finger:0}}],'relative_target',targets=initial)
    for finger in ('middle','ring','thumb'):
        pair('sequence',(f'set {finger} to 25% then set {finger} to 75% then set {finger} to 25%',
                         f'Move only the {finger} through one-quarter, three-quarters, then one-quarter opening'),
             [{'action':'pose','fingers':{finger:v}} for v in (25,75,25)],'intermediate_targets',targets=initial)
    for first,second in [('index','thumb'),('middle','ring')]:
        pair('sequence',(f'set {first} to 25% and {second} to 75% then set {first} to 75% and {second} to 25%',
                         f'First put the {first} at 25% and {second} at 75%, then exchange those openings; keep other fingers unchanged'),
             [{'action':'pose','fingers':{first:25,second:75}},{'action':'pose','fingers':{first:75,second:25}}],
             'paired_exchange',targets=initial)
    for actions in [('peace','point','peace'),('open','yes','close','open')]:
        pair('sequence',(' then '.join('show '+a for a in actions),'Perform these gestures in order: '+', '.join(actions)),
             [{'action':a} for a in actions],'ordered_gestures')
    for texts,result,skill in [
        (('1 + 2','Display the sum of one and two'),3,'addition_single_group'),
        (('20 - 3','Show twenty minus three'),17,'subtraction_groups'),
        (('2 * 2','Show two multiplied by two'),4,'multiplication_single_group'),
        (('20 / 2','Divide twenty by two and display the result'),10,'division_groups'),
        (('18 - 2 * 3','Show eighteen minus the product of two and three'),12,'precedence')]:
        pair('arithmetic',texts,[{'action':'number','number':result}],skill)
    for row in rows:row['suite_version']='control-200-v4'
    return rows
